"""Operation-scoped package reads and immutable, content-bound revision products."""

from __future__ import annotations
import os
import stat
from collections.abc import Mapping
from pathlib import Path
from types import MappingProxyType
from typing import Any
import yaml


_REPARSE_POINT = getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0x400)


class PackageContentChangedError(ValueError):
    """The package changed while its products were being constructed."""


def freeze_package_value(value: Any) -> Any:
    if isinstance(value, Mapping):
        return MappingProxyType({key: freeze_package_value(item) for key, item in value.items()})
    if isinstance(value, (list, tuple)):
        return tuple(freeze_package_value(item) for item in value)
    if isinstance(value, (set, frozenset)):
        return frozenset(freeze_package_value(item) for item in value)
    return value


def materialize_package_value(value: Any) -> Any:
    """Return detached containers for legacy parsers and public return values."""
    if isinstance(value, Mapping):
        return {key: materialize_package_value(item) for key, item in value.items()}
    if isinstance(value, tuple):
        return [materialize_package_value(item) for item in value]
    if isinstance(value, frozenset):
        return {materialize_package_value(item) for item in value}
    return value


def read_package_bytes(root: Path, relative: str) -> bytes:
    """Check the physical boundary on every access, including hidden controls."""
    root = Path(os.path.abspath(root))
    relative_path = Path(relative)
    parts = relative_path.parts
    if not parts:
        raise ValueError("Unsafe ontology revision path")
    if relative_path.is_absolute() or relative_path.drive or ".." in parts:
        raise ValueError("Unsafe ontology revision path")
    candidate = root
    for part in ("", *parts):
        candidate = candidate / part
        info = candidate.lstat()
        if stat.S_ISLNK(info.st_mode) or getattr(info, "st_file_attributes", 0) & _REPARSE_POINT:
            raise ValueError("Ontology package contains symbolic links or junctions")
    if not stat.S_ISREG(info.st_mode):
        raise OSError("Ontology package entry must be a regular file")
    candidate.resolve(strict=True).relative_to(root.resolve(strict=True))
    flags = os.O_RDONLY | getattr(os, "O_BINARY", 0) | getattr(os, "O_NOFOLLOW", 0)
    descriptor = os.open(candidate, flags, mode=0o600)
    with os.fdopen(descriptor, "rb") as stream:
        opened = os.fstat(stream.fileno())
        if not stat.S_ISREG(opened.st_mode):
            raise OSError("Ontology package entry must be a regular file")
        payload = stream.read()
        final = candidate.lstat()
        if (
            (opened.st_dev, opened.st_ino) != (final.st_dev, final.st_ino)
            or stat.S_ISLNK(final.st_mode)
            or getattr(final, "st_file_attributes", 0) & _REPARSE_POINT
        ):
            raise PackageContentChangedError("Ontology package changed while being read")
    return payload


class PackageReadSession:
    """Memoize source bytes and basic YAML parsing within one operation only.

    Callers keep their existing strict or lenient grammar and error adapters.
    A snapshot is published only after rereading the bytes used by its parsers.
    """

    def __init__(self, root: Path) -> None:
        self._lexical_root = Path(os.path.abspath(root))
        if self._lexical_root.exists() or self._lexical_root.is_symlink():
            info = self._lexical_root.lstat()
            if stat.S_ISLNK(info.st_mode) or getattr(info, "st_file_attributes", 0) & _REPARSE_POINT:
                raise ValueError("Ontology revision must be a regular directory")
        # A trusted parent can have an OS alias, such as macOS /var. Keep both
        # root spellings without resolving file components past the boundary.
        self.root = self._lexical_root.resolve()
        self._bytes: dict[str, bytes] = {}
        self._yaml: dict[str, Any] = {}

    def relative_path(self, path: Path) -> str:
        candidate = Path(os.path.abspath(path))
        try:
            return candidate.relative_to(self._lexical_root).as_posix()
        except ValueError:
            return candidate.relative_to(self.root).as_posix()

    def read_text(self, path: Path) -> str:
        relative = self.relative_path(path)
        if relative not in self._bytes:
            self._bytes[relative] = read_package_bytes(self.root, relative)
        # Match Path.read_text's universal newline handling, retaining raw hashes.
        return self._bytes[relative].decode("utf-8").replace("\r\n", "\n").replace("\r", "\n")

    def parse_yaml(self, source: str) -> Any:
        if source not in self._yaml:
            parsed = yaml.safe_load(source)
            try:
                self._yaml[source] = freeze_package_value(parsed)
            except RecursionError:
                # Ignored legacy metadata can contain recursive YAML aliases.
                # Preserve its parser behavior without sharing a mutable graph.
                return parsed
        return materialize_package_value(self._yaml[source])

    def assert_unchanged(self) -> None:
        for relative, payload in self._bytes.items():
            if read_package_bytes(self.root, relative) != payload:
                raise PackageContentChangedError("Ontology package changed while being read")
